patch.diff:
--- a/apps/minishop/src/store/cartStore.ts
+++ b/apps/minishop/src/store/cartStore.ts
@@ -12,7 +12,7 @@ export const useCartStore = create<CartStore>((set, get) => ({
   addItem: (product) =>
     set((state) => ({ items: [...state.items, product] })),

-  total: () => get().items[0]?.price ?? 0,
+  total: () => get().items.reduce((sum, item) => sum + item.price, 0),
 }));
